import { createRoute, z } from '@hono/zod-openapi'

const ASTNodeInputSchema: z.ZodType<ASTNodeInputType> = z
  .lazy(() =>
    z
      .xor([
        ASTStringNodeInputSchema.openapi({ description: 'String literal.' }),
        ASTNumberNodeInputSchema.openapi({ description: 'Number literal.' }),
        ASTBooleanNodeInputSchema.openapi({ description: 'Boolean literal.' }),
        ASTNullNodeInputSchema.openapi({ description: 'Null literal.' }),
        ASTLLMNodeInputSchema.openapi({
          description: 'Value extracted by an LLM according to the given schema.',
        }),
        ASTDynamicVariableNodeInputSchema.openapi({
          description: 'Reference to a dynamic variable.',
        }),
        ASTOrOperatorNodeInputSchema.openapi({
          description: 'Evaluates to true if any child is true.',
        }),
        ASTAndOperatorNodeInputSchema.openapi({
          description: 'Evaluates to true if all children are true.',
        }),
        ASTEqualsOperatorNodeInputSchema.openapi({
          description: 'Evaluates to true if the left value equals the right.',
        }),
        ASTNotEqualsOperatorNodeInputSchema.openapi({
          description: 'Evaluates to true if the left value does not equal the right.',
        }),
        ASTGreaterThanOperatorNodeInputSchema.openapi({
          description: 'Evaluates to true if the left value is greater than the right.',
        }),
        ASTLessThanOperatorNodeInputSchema.openapi({
          description: 'Evaluates to true if the left value is less than the right.',
        }),
        ASTGreaterThanOrEqualsOperatorNodeInputSchema.openapi({
          description: 'Evaluates to true if the left value is greater than or equal to the right.',
        }),
        ASTLessThanOrEqualsOperatorNodeInputSchema.openapi({
          description: 'Evaluates to true if the left value is less than or equal to the right.',
        }),
        ASTAdditionOperatorNodeInputSchema.openapi({
          description: 'Adds the left and right values.',
        }),
        ASTSubtractionOperatorNodeInputSchema.openapi({
          description: 'Subtracts the right value from the left.',
        }),
        ASTMultiplicationOperatorNodeInputSchema.openapi({
          description: 'Multiplies the left value times the right.',
        }),
        ASTDivisionOperatorNodeInputSchema.openapi({
          description: 'Divides the left value by the right.',
        }),
        ASTConditionalOperatorNodeInputSchema.openapi({
          description:
            'Selects one of two expressions based on whether the given condition evaluates to true.',
        }),
      ])
      .openapi({
        discriminator: {
          propertyName: 'type',
          mapping: {
            add_operator: '#/components/schemas/ASTAdditionOperatorNode-Input',
            and_operator: '#/components/schemas/ASTAndOperatorNode-Input',
            boolean_literal: '#/components/schemas/ASTBooleanNode-Input',
            conditional_operator: '#/components/schemas/ASTConditionalOperatorNode-Input',
            div_operator: '#/components/schemas/ASTDivisionOperatorNode-Input',
            dynamic_variable: '#/components/schemas/ASTDynamicVariableNode-Input',
            eq_operator: '#/components/schemas/ASTEqualsOperatorNode-Input',
            gt_operator: '#/components/schemas/ASTGreaterThanOperatorNode-Input',
            gte_operator: '#/components/schemas/ASTGreaterThanOrEqualsOperatorNode-Input',
            llm: '#/components/schemas/ASTLLMNode-Input',
            lt_operator: '#/components/schemas/ASTLessThanOperatorNode-Input',
            lte_operator: '#/components/schemas/ASTLessThanOrEqualsOperatorNode-Input',
            mul_operator: '#/components/schemas/ASTMultiplicationOperatorNode-Input',
            neq_operator: '#/components/schemas/ASTNotEqualsOperatorNode-Input',
            null_literal: '#/components/schemas/ASTNullNode-Input',
            number_literal: '#/components/schemas/ASTNumberNode-Input',
            or_operator: '#/components/schemas/ASTOrOperatorNode-Input',
            string_literal: '#/components/schemas/ASTStringNode-Input',
            sub_operator: '#/components/schemas/ASTSubtractionOperatorNode-Input',
          },
        },
      }),
  )
  .openapi('ASTNodeInput')

type ASTAdditionOperatorNodeInputType = {
  type?: 'add_operator'
  left: z.infer<typeof ASTNodeInputSchema>
  right: z.infer<typeof ASTNodeInputSchema>
}

