const LLMLiteralJsonSchemaPropertySchema = z
  .object({
    type: z
      .union([z.enum(['boolean', 'string', 'integer', 'number']), z.array(z.string()).length(2)])
      .openapi({ title: 'Type' }),
    description: z.string().min(0).openapi({ title: 'Description' }),
    enum: z
      .union([z.array(z.string()), z.null().nullable()])
      .exactOptional()
      .openapi({
        title: 'Enum',
        description: 'List of allowed string values for string type parameters',
      }),
  })
  .openapi({ required: ['type', 'description'], title: 'LLMLiteralJsonSchemaProperty' })
  .openapi('LLMLiteralJsonSchemaProperty')

type ASTLLMNodeInputType =
  | { type?: 'llm'; value_schema: z.infer<typeof LLMLiteralJsonSchemaPropertySchema> }
  | { type?: 'llm'; prompt: string }

type ASTLLMNodeOutputType = {
  type: 'llm'
  value_schema: z.infer<typeof LLMLiteralJsonSchemaPropertySchema>
  prompt: string
}

