type ASTStringNodeInputType = { type?: 'string_literal'; value: string }

const ASTStringNodeInputSchema: z.ZodType<ASTStringNodeInputType> = z
  .object({
    type: z
      .literal('string_literal')
      .default('string_literal')
      .exactOptional()
      .openapi({ title: 'Type' }),
    value: z.string().openapi({ title: 'Value', description: 'Value of this literal.' }),
  })
  .openapi({ required: ['value'], title: 'ASTStringNode' })
  .openapi('ASTStringNodeInput')

type ASTNumberNodeInputType = { type?: 'number_literal'; value: number | number }

const ASTNumberNodeInputSchema: z.ZodType<ASTNumberNodeInputType> = z
