const SoftTimeoutConfigSchema = z
  .object({
    timeout_seconds: z
      .number()
      .default(-1)
      .exactOptional()
      .openapi({
        title: 'Timeout Seconds',
        description:
          'Time in seconds before showing the predefined message while waiting for LLM response. Set to -1 to disable.',
      }),
    message: z
      .string()
      .min(1)
      .max(200)
      .default('Hhmmmm...yeah.')
      .exactOptional()
      .openapi({
        title: 'Message',
        description:
          'Message to show when the first soft timeout is reached while waiting for LLM response. Supports dynamic variables (e.g., {{system__time}}, {{custom_variable}}).',
        'x-convai-client-override': true,
        'x-convai-language-override': true,
      }),
    additional_soft_timeout_messages: z
      .array(z.string())
      .max(7)
      .exactOptional()
      .openapi({
        title: 'Additional Soft Timeout Messages',
        description:
          'Extra static filler messages for subsequent soft timeouts in the same LLM generation. The first timeout uses `message`. If fewer messages are configured than `max_soft_timeouts_per_generation`, the last configured message is repeated; otherwise a built-in filler is used.',
        'x-convai-client-override': true,
        'x-convai-language-override': true,
      }),
    use_llm_generated_message: z
      .boolean()
      .default(false)
      .exactOptional()
      .openapi({
        title: 'Use Llm Generated Message',
        description:
          'If enabled, the soft timeout message will be generated dynamically instead of using the static message.',
      }),
    randomize_fillers: z
      .boolean()
      .default(false)
      .exactOptional()
      .openapi({
        title: 'Randomize Fillers',
        description:
          'If enabled, shuffle the order of static soft timeout messages once at the start of each turn. Only applies when use_llm_generated_message is false.',
      }),
    max_soft_timeouts_per_generation: z
      .int()
      .min(1)
      .max(8)
      .default(1)
      .exactOptional()
      .openapi({
        title: 'Max Soft Timeouts Per Generation',
        description:
          'Maximum filler messages while waiting for a single LLM response. Fires every timeout_seconds until the LLM streams content or this limit is reached.',
      }),
    llm_generated_message_prompt_override: z
      .union([z.string().min(1).max(1000), z.null().nullable()])
      .exactOptional()
      .openapi({
        title: 'Llm Generated Message Prompt Override',
        description:
          'Custom prompt for generating the soft timeout filler message when use_llm_generated_message is enabled. Recent conversation context is provided as a separate user message. If not set, the default prompt will be used. Supports dynamic variables (e.g., {{system__time}}, {{custom_variable}}).',
        examples: [
          'Output a SHORT neutral filler phrase (1-4 words MAX) acknowledging you heard the user.',
        ],
      }),
    disable_until_first_user_message: z
      .boolean()
      .default(false)
      .exactOptional()
      .openapi({
        title: 'Disable Until First User Message',
        description:
          "When true, soft timeout fillers are suppressed until the conversation has at least one real user message. Prevents fillers during the agent's opening turn (e.g. workflow generate-immediately / tool calls before the user speaks).",
      }),
  })
  .openapi({
    title: 'SoftTimeoutConfig',
    description: 'Configuration for soft timeout functionality during LLM response generation.',
    example: { message: 'Hhmmmm...yeah.', timeout_seconds: 2, use_llm_generated_message: false },
    required: [],
  })
  .openapi('SoftTimeoutConfig')

const TurnConfigSchema = z
  .object({
    turn_timeout: z
      .number()
      .default(7)
      .exactOptional()
      .openapi({
        title: 'Turn Timeout',
        description: "Maximum wait time for the user's reply before re-engaging the user",
      }),
    initial_wait_time: z
      .union([z.number(), z.null().nullable()])
      .exactOptional()
      .openapi({
        title: 'Initial Wait Time',
        description:
          'How long the agent will wait for the user to start the conversation if the first message is empty. If not set, uses the regular turn_timeout.',
      }),
    silence_end_call_timeout: z
      .number()
      .default(-1)
      .exactOptional()
      .openapi({
        title: 'Silence End Call Timeout',
        description: 'Maximum wait time since the user last spoke before terminating the call',
      }),
    mode: TurnModeSchema.default('turn')
      .exactOptional()
      .openapi({ description: 'The mode of turn detection', 'x-fern-ignore': true }),
    turn_eagerness: TurnEagernessSchema.default('normal')
      .exactOptional()
      .openapi({
        description:
          'Controls how eager the agent is to respond. Low = less eager (waits longer), Standard = default eagerness, High = more eager (responds sooner)',
      }),
    spelling_patience: SpellingPatienceSchema.default('auto')
      .exactOptional()
      .openapi({
        description:
          'Controls if the agent should be more patient when user is spelling numbers and named entities. Auto = model based, Off = never wait extra',
      }),
    speculative_turn: z
      .boolean()
      .default(false)
      .exactOptional()
      .openapi({
        title: 'Speculative Turn',
        description:
          'When enabled, starts generating LLM responses during silence before full turn confidence is reached, reducing perceived latency. May increase LLM costs.',
      }),
    retranscribe_on_turn_timeout: z
      .boolean()
      .default(false)
      .exactOptional()
      .openapi({
        title: 'Retranscribe On Turn Timeout',
        description:
          'When enabled, if VAD detects no speech, attempts to re-transcribe accumulated audio at turn timeout. Disables silence discount billing while enabled for the active agent or workflow node.',
      }),
    turn_model: TurnModelSchema.default('turn_v3').exactOptional(),
    interruption_ignore_terms: z
      .array(z.string())
      .exactOptional()
      .openapi({
        title: 'Interruption Ignore Terms',
        description:
          "List of terms that should not trigger an interruption when spoken by the user (e.g. 'gotcha', 'understood'). Uses case-insensitive exact matching.",
      }),
    interruption_ignore_term_languages: z
      .array(z.string())
      .exactOptional()
      .openapi({
        title: 'Interruption Ignore Term Languages',
        description:
          'Language codes for which preset ignore-term categories have been activated. Stored explicitly so display is not inferred from term overlap.',
      }),
    merge_with_default_ignore_terms: z
      .boolean()
      .default(false)
      .exactOptional()
      .openapi({
        title: 'Merge With Default Ignore Terms',
        description:
          'When enabled, the curated default terms for interruption_ignore_term_languages are used in addition to interruption_ignore_terms.',
      }),
    transcribe_on_disabled_interruptions: z
      .boolean()
      .default(false)
      .exactOptional()
      .openapi({
        title: 'Transcribe On Disabled Interruptions',
        description:
          "When interruptions are disabled, still transcribe what the user says so it can carry into the next turn. When off, user speech during a non-interruptible turn is ignored and won't trigger a turn.",
      }),
    soft_timeout_config: SoftTimeoutConfigSchema.exactOptional().openapi({
      description:
        'Configuration for soft timeout functionality. Provides immediate feedback during longer LLM responses.',
    }),
  })
  .openapi({
    title: 'TurnConfig',
    example: {
      interruption_ignore_term_languages: [],
      interruption_ignore_terms: [],
      merge_with_default_ignore_terms: false,
      mode: 'turn',
      retranscribe_on_turn_timeout: false,
      silence_end_call_timeout: -1,
      soft_timeout_config: { message: 'Hhmmmm...yeah.', timeout_seconds: -1 },
      speculative_turn: false,
      spelling_patience: 'auto',
      transcribe_on_disabled_interruptions: false,
      turn_eagerness: 'normal',
      turn_model: 'turn_v3',
      turn_timeout: 7,
    },
    required: [],
  })
  .openapi('TurnConfig')

