const CustomSIPHeaderSchema = z
  .object({
    type: z.literal('static').default('static').exactOptional().openapi({ title: 'Type' }),
    key: z
      .string()
      .regex(/^[A-Za-z0-9]+(-[A-Za-z0-9]+)*$/)
      .min(1)
      .max(64)
      .openapi({ title: 'Key', description: "The SIP header name (e.g., 'X-Customer-ID')" }),
    value: z
      .string()
      .regex(/^[\x09\x20-\x7E]+$/)
      .min(1)
      .max(512)
      .openapi({ title: 'Value', description: 'The header value' }),
  })
  .openapi({
    required: ['key', 'value'],
    title: 'CustomSIPHeader',
    description: 'Custom SIP header for phone transfers with a static (validated) value.',
  })
  .openapi('CustomSIPHeader')

const CustomSIPHeaderWithDynamicVariableSchema = z
  .object({
    value: z
      .string()
      .min(1)
      .openapi({ title: 'Value', description: 'The dynamic variable name to resolve' }),
    type: z.literal('dynamic').openapi({ title: 'Type' }),
    key: z
      .string()
      .regex(/^[A-Za-z0-9]+(-[A-Za-z0-9]+)*$/)
      .min(1)
      .max(64)
      .openapi({ title: 'Key', description: "The SIP header name (e.g., 'X-Customer-ID')" }),
  })
  .openapi({
    required: ['value', 'type', 'key'],
    title: 'CustomSIPHeaderWithDynamicVariable',
    description:
      'Custom SIP header for phone transfers with a dynamic variable reference.\nThe value is a variable name that will be resolved at runtime.\nValue is not validated here since it will be substituted with actual value later.',
  })
  .openapi('CustomSIPHeaderWithDynamicVariable')

