const UUITransferConfigSchema = z
  .object({
    data: z
      .string()
      .max(8192)
      .openapi({
        title: 'Data',
        description:
          'UUI payload to send on SIP REFER transfers. Supports inline dynamic variables and is hex-encoded at transfer time.',
      }),
    protocol_discriminator: z
      .union([z.string().regex(/^[0-9A-Fa-f]{2}$/), z.null().nullable()])
      .exactOptional()
      .openapi({
        title: 'Protocol Discriminator',
        description:
          "Optional one-octet protocol discriminator (two hex digits, e.g. '00'). Required by platforms such as Genesys Cloud, which otherwise strip the first octet of the payload. Leave unset for platforms like Talkdesk that expect a bare hex payload.",
      }),
    protocol_discriminator_mode: z
      .enum(['prefix', 'pd_parameter'])
      .default('prefix')
      .exactOptional()
      .openapi({
        title: 'Protocol Discriminator Mode',
        description:
          "How to attach protocol_discriminator. 'prefix' prepends the octet to the hex payload (User-to-User=XX<hex>;encoding=hex). 'pd_parameter' sends it as a separate parameter (User-to-User=<hex>;pd=XX;encoding=hex). Ignored when protocol_discriminator is unset.",
      }),
  })
  .openapi({
    required: ['data'],
    title: 'UUITransferConfig',
    description:
      'User-to-User Information envelope for SIP REFER transfers (RFC 7433).\n\nOutbound payloads are hex-encoded (the only encoding RFC 7433 defines). The\nprotocol discriminator axis lets per-platform formats (Talkdesk, Genesys, ...)\nbe expressed by configuration rather than scattered transfer flags. Further\naxes (ASCII encoding, header name, purpose/content parameters) can be added\nhere without touching the transfer model.',
  })
  .openapi('UUITransferConfig')

