const PhoneNumberTransferSchema = z
  .object({
    custom_sip_headers: z
      .array(
        z
          .xor([CustomSIPHeaderSchema, CustomSIPHeaderWithDynamicVariableSchema])
          .openapi({
            discriminator: {
              propertyName: 'type',
              mapping: {
                dynamic: '#/components/schemas/CustomSIPHeaderWithDynamicVariable',
                static: '#/components/schemas/CustomSIPHeader',
              },
            },
          }),
      )
      .max(20)
      .exactOptional()
      .openapi({
        title: 'Custom Sip Headers',
        description:
          'Custom SIP headers to include when transferring the call. Each header can be either a static value or a dynamic variable reference.',
      }),
    transfer_destination: z
      .xor([
        PhoneNumberTransferDestinationSchema,
        SIPUriTransferDestinationSchema,
        PhoneNumberDynamicVariableTransferDestinationSchema,
        SIPUriDynamicVariableTransferDestinationSchema,
      ])
      .openapi({
        title: 'Transfer Destination',
        discriminator: {
          propertyName: 'type',
          mapping: {
            phone: '#/components/schemas/PhoneNumberTransferDestination',
            phone_dynamic_variable:
              '#/components/schemas/PhoneNumberDynamicVariableTransferDestination',
            sip_uri: '#/components/schemas/SIPUriTransferDestination',
            sip_uri_dynamic_variable:
              '#/components/schemas/SIPUriDynamicVariableTransferDestination',
          },
        },
      }),
    transfer_type: TransferTypeEnumSchema.default('conference').exactOptional(),
    sip_refer_play_dialtone: z
      .boolean()
      .default(true)
      .exactOptional()
      .openapi({
        title: 'Sip Refer Play Dialtone',
        description:
          'When True, a ringing tone is played on the original call leg while a SIP REFER transfer completes. The tone is carried over RTP to the SIP peer executing the REFER, so disable this if the receiving system (e.g. an SBC or contact center) should not hear it. When disabled the caller hears silence until the transfer completes. SIP REFER transfers only.',
      }),
    uui: z
      .union([UUITransferConfigSchema, z.null().nullable()])
      .exactOptional()
      .openapi({
        description:
          'User-to-User Information (RFC 7433) to attach to SIP REFER transfers. Carries call context such as CRM identifiers or escalation reason across the transfer boundary.',
      }),
    post_dial_digits: z
      .union([
        z
          .xor([PostDialDigitsStaticSchema, PostDialDigitsDynamicVariableSchema])
          .openapi({
            discriminator: {
              propertyName: 'type',
              mapping: {
                dynamic: '#/components/schemas/PostDialDigitsDynamicVariable',
                static: '#/components/schemas/PostDialDigitsStatic',
              },
            },
          }),
        z.null().nullable(),
      ])
      .exactOptional()
      .openapi({
        title: 'Post Dial Digits',
        description:
          "DTMF digits to send after call connects (e.g., 'ww1234' for extension). Can be either a static value or a dynamic variable reference. Use 'w' for 0.5s pause. Only supported for Twilio transfers.",
      }),
    phone_number: z
      .union([z.string(), z.null().nullable()])
      .exactOptional()
      .openapi({ title: 'Phone Number', deprecated: true }),
    condition: z.string().openapi({ title: 'Condition' }),
  })
  .openapi({ required: ['transfer_destination', 'condition'], title: 'PhoneNumberTransfer' })
  .openapi('PhoneNumberTransfer')

