const SkipTurnToolConfigSchema = z
  .object({
    system_tool_type: z
      .literal('skip_turn')
      .default('skip_turn')
      .exactOptional()
      .openapi({ title: 'System Tool Type' }),
    wait_timeout_secs: z
      .number()
      .default(-1)
      .exactOptional()
      .openapi({
        title: 'Wait Timeout Secs',
        description:
          'Seconds to wait after skip_turn before the agent generates a contextual check-in. The "End conversation after silence" timer is paused during the wait. -1 disables the wait: after skip_turn the agent stays silent until the caller speaks, and that timer keeps running. Applies to voice conversations only.',
      }),
  })
  .openapi({
    title: 'SkipTurnToolConfig',
    description:
      'Allows the agent to explicitly skip its turn.\n\nThis tool should be invoked by the LLM when the user indicates they would like\nto think or take a short pause before continuing the conversation—e.g. when\nthey say: "Give me a second", "Let me think", or "One moment please".  After\ncalling this tool, the assistant should not speak until the user speaks\nagain, or if wait_timeout_secs is set, until that wait elapses and the\nagent generates a check-in.',
    required: [],
  })
  .openapi('SkipTurnToolConfig')

const PlayDTMFToolConfigSchema = z
