const SystemToolConfigInputSchema = z
  .object({
    type: z
      .literal('system')
      .default('system')
      .exactOptional()
      .openapi({ title: 'Type', description: 'The type of tool' }),
    name: z
      .string()
      .regex(/^[a-zA-Z0-9_-]{1,64}$/)
      .min(0)
      .openapi({ title: 'Name' }),
    description: z
      .string()
      .min(0)
      .default('')
      .exactOptional()
      .openapi({
        title: 'Description',
        description:
          "Description of when the tool should be used and what it does. Leave empty to use the default description that's optimized for the specific tool type.",
      }),
    response_timeout_secs: z
      .int()
      .default(20)
      .exactOptional()
      .openapi({
        title: 'Response Timeout Secs',
        description: 'The maximum time in seconds to wait for the tool call to complete.',
      }),
    disable_interruptions: z
      .boolean()
      .default(false)
      .exactOptional()
      .openapi({
        title: 'Disable Interruptions',
        description:
          'DEPRECATED: use `interruption_mode` instead. If true, the user will not be able to interrupt the agent while this tool is running.',
        deprecated: true,
      }),
    interruption_mode: ToolInterruptionModeSchema.default('allow')
      .exactOptional()
      .openapi({
        description:
          "Controls whether the user can interrupt the agent around this tool call. 'allow' (default) lets the user interrupt at any time, 'disable_during_tool' suppresses interruptions only while the tool is running, 'disable_during_tool_and_turn' suppresses interruptions while the tool runs and for the agent response that follows it.",
      }),
    force_pre_tool_speech: z
      .boolean()
      .default(false)
      .exactOptional()
      .openapi({
        title: 'Force Pre Tool Speech',
        description:
          'DEPRECATED: use `pre_tool_speech` instead. If true, the agent will speak before the tool call.',
        deprecated: true,
      }),
    pre_tool_speech: PreToolSpeechModeSchema.default('auto')
      .exactOptional()
      .openapi({
        description:
          "Controls whether the agent speaks before this tool is called. 'auto' (default) decides based on recent tool latency, 'force' always asks the agent to speak, 'off' fully opts out regardless of latency.",
      }),
    assignments: z
      .array(DynamicVariableAssignmentSchema)
      .exactOptional()
      .openapi({
        title: 'Assignments',
        description:
          'Configuration for extracting values from tool responses and assigning them to dynamic variables',
      }),
    tool_call_sound: z
      .union([ToolCallSoundTypeSchema, z.null().nullable()])
      .exactOptional()
      .openapi({
        description:
          'Predefined tool call sound type to play during tool execution. If not specified, no tool call sound will be played.',
        'x-convai-client-override': true,
      }),
    tool_call_sound_behavior: ToolCallSoundBehaviorSchema.default('auto')
      .exactOptional()
      .openapi({
        description:
          "Determines when the tool call sound should play. 'auto' only plays when there's pre-tool speech, 'always' plays for every tool call.",
      }),
    tool_error_handling_mode: ToolErrorHandlingModeSchema.default('auto')
      .exactOptional()
      .openapi({
        description:
          "Controls how tool errors are processed before being shared with the agent. 'auto' determines handling based on tool type (summarized for native integrations, hide for others), 'summarized' sends an LLM-generated summary, 'passthrough' sends the raw error, 'hide' does not share the error with the agent.",
      }),
    params: z
      .xor([
        EndCallToolConfigSchema,
        LanguageDetectionToolConfigSchema,
        TransferToAgentToolConfigInputSchema,
        TransferToNumberToolConfigInputSchema,
        SkipTurnToolConfigSchema,
        PlayDTMFToolConfigSchema,
        VoicemailDetectionToolConfigSchema,
        KnowledgeBaseRagToolConfigSchema,
        KnowledgeBaseToolConfigSchema,
        StartProcedureToolConfigSchema,
        EndProcedureToolConfigSchema,
      ])
      .openapi({
        title: 'Params',
        discriminator: {
          propertyName: 'system_tool_type',
          mapping: {
            end_call: '#/components/schemas/EndCallToolConfig',
            end_procedure: '#/components/schemas/EndProcedureToolConfig',
            knowledge_base: '#/components/schemas/KnowledgeBaseToolConfig',
            knowledge_base_rag: '#/components/schemas/KnowledgeBaseRagToolConfig',
            language_detection: '#/components/schemas/LanguageDetectionToolConfig',
            play_keypad_touch_tone: '#/components/schemas/PlayDTMFToolConfig',
            skip_turn: '#/components/schemas/SkipTurnToolConfig',
            start_procedure: '#/components/schemas/StartProcedureToolConfig',
            transfer_to_agent: '#/components/schemas/TransferToAgentToolConfig-Input',
            transfer_to_number: '#/components/schemas/TransferToNumberToolConfig-Input',
            voicemail_detection: '#/components/schemas/VoicemailDetectionToolConfig',
          },
        },
      }),
  })
  .openapi({
    required: ['name', 'params'],
    title: 'SystemToolConfig',
    description: 'A system tool is a tool that is used to call a system method in the server',
    examples: [
      {
        description: '',
        name: 'end_call',
        params: { system_tool_type: 'end_call' },
        type: 'system',
      },
      {
        description: 'Custom description for specific use case',
        name: 'transfer_to_agent',
        params: { system_tool_type: 'transfer_to_agent', transfers: [] },
        type: 'system',
      },
    ],
  })
  .openapi('SystemToolConfigInput')

