const AnalysisScopeSchema = z
  .enum(['conversation', 'agent'])
  .default('conversation')
  .openapi({ title: 'AnalysisScope' })
  .openapi('AnalysisScope')

const CriteriaScoringModeSchema = z
  .enum(['binary', 'numeric_uniform'])
  .default('binary')
  .openapi({ title: 'CriteriaScoringMode' })
  .openapi('CriteriaScoringMode')

const PromptEvaluationCriteriaSchema = z
  .object({
    id: z
      .string()
      .openapi({ title: 'Id', description: 'The unique identifier for the evaluation criteria' }),
    name: z.string().openapi({ title: 'Name' }),
    type: z
      .literal('prompt')
      .default('prompt')
      .exactOptional()
      .openapi({ title: 'Type', description: 'The type of evaluation criteria' }),
    conversation_goal_prompt: z
      .string()
      .max(2000)
      .openapi({
        title: 'Conversation Goal Prompt',
        description: 'The prompt that the agent should use to evaluate the conversation',
      }),
    use_knowledge_base: z
      .boolean()
      .default(false)
      .exactOptional()
      .openapi({
        title: 'Use Knowledge Base',
        description: "When evaluating the prompt, should the agent's knowledge base be used.",
      }),
    scope: AnalysisScopeSchema.default('conversation')
      .exactOptional()
      .openapi({
        description:
          "The scope of transcript context used when evaluating this criterion. 'conversation' uses the full transcript; 'agent' uses only the portion where the defining agent was active.",
      }),
    llm: z
      .union([LLMSchema, z.null().nullable()])
      .exactOptional()
      .openapi({
        description:
          "LLM model to use for this evaluation criteria. If not set, uses agent's analysis_llm default.",
      }),
    scoring_mode: CriteriaScoringModeSchema.default('binary')
      .exactOptional()
      .openapi({
        description:
          "How this criterion is scored. 'binary' resolves to success/failure/unknown. 'numeric_uniform' returns a number on the [0, max_score] scale which is normalized into the aggregate conversation success percentage.",
      }),
    max_score: z
      .int()
      .default(100)
      .exactOptional()
      .openapi({
        title: 'Max Score',
        description:
          "Maximum value of the numeric score scale (minimum is always 0). Only used when scoring_mode is 'numeric_uniform'.",
      }),
    score_instructions: z
      .union([z.string().max(2000), z.null().nullable()])
      .exactOptional()
      .openapi({
        title: 'Score Instructions',
        description:
          "Optional free-text instructions describing how to assign values on the numeric scale. Only used when scoring_mode is 'numeric_uniform'.",
      }),
  })
  .openapi({
    required: ['id', 'name', 'conversation_goal_prompt'],
    title: 'PromptEvaluationCriteria',
    description: 'An evaluation using the transcript and a prompt for a yes/no achieved answer',
    examples: [
      {
        conversation_goal_prompt: "Determine whether the agent fully resolved the user's issue.",
        id: 'criterion_binary_001',
        max_score: 100,
        name: 'Issue resolved',
        scope: 'conversation',
        scoring_mode: 'binary',
        use_knowledge_base: false,
      },
      {
        conversation_goal_prompt: 'Rate how completely and correctly the issue was resolved.',
        id: 'criterion_numeric_001',
        max_score: 100,
        name: 'Resolution quality',
        scope: 'conversation',
        score_instructions:
          '0 means unresolved, 50 means partially resolved, 100 means fully resolved with correct details.',
        scoring_mode: 'numeric_uniform',
        use_knowledge_base: false,
      },
    ],
  })
  .openapi('PromptEvaluationCriteria')

