const WorkflowEdgeModelInputSchema = z
  .object({
    source: z.string().openapi({ title: 'Source', description: 'ID of the source node.' }),
    target: z.string().openapi({ title: 'Target', description: 'ID of the target node.' }),
    forward_condition: z
      .union([
        z
          .xor([
            WorkflowUnconditionalModelInputSchema.openapi({
              description: 'Condition that is always true.',
            }),
            WorkflowLLMConditionModelInputSchema.openapi({
              description: 'Condition described using human language and evaluated by an LLM.',
            }),
            WorkflowResultConditionModelInputSchema.openapi({
              description: 'Condition based on the result of the last executed tool dispatch node.',
            }),
            WorkflowExpressionConditionModelInputSchema.openapi({
              description: 'Condition described using a deterministic expression.',
            }),
          ])
          .openapi({
            discriminator: {
              propertyName: 'type',
              mapping: {
                expression: '#/components/schemas/WorkflowExpressionConditionModel-Input',
                llm: '#/components/schemas/WorkflowLLMConditionModel-Input',
                result: '#/components/schemas/WorkflowResultConditionModel-Input',
                unconditional: '#/components/schemas/WorkflowUnconditionalModel-Input',
              },
            },
          }),
        z.null().nullable(),
      ])
      .exactOptional()
      .openapi({
        title: 'Forward Condition',
        description:
          'Condition that must be met for the edge to be traversed in the forward direction (source to target).',
      }),
    backward_condition: z
      .union([
        z
          .xor([
            WorkflowUnconditionalModelInputSchema.openapi({
              description: 'Condition that is always true.',
            }),
            WorkflowLLMConditionModelInputSchema.openapi({
              description: 'Condition described using human language and evaluated by an LLM.',
            }),
            WorkflowResultConditionModelInputSchema.openapi({
              description: 'Condition based on the result of the last executed tool dispatch node.',
            }),
            WorkflowExpressionConditionModelInputSchema.openapi({
              description: 'Condition described using a deterministic expression.',
            }),
          ])
          .openapi({
            discriminator: {
              propertyName: 'type',
              mapping: {
                expression: '#/components/schemas/WorkflowExpressionConditionModel-Input',
                llm: '#/components/schemas/WorkflowLLMConditionModel-Input',
                result: '#/components/schemas/WorkflowResultConditionModel-Input',
                unconditional: '#/components/schemas/WorkflowUnconditionalModel-Input',
              },
            },
          }),
        z.null().nullable(),
      ])
      .exactOptional()
      .openapi({
        title: 'Backward Condition',
        description:
          'Condition that must be met for the edge to be traversed in the backward direction (target to source).',
      }),
  })
  .openapi({ required: ['source', 'target'], title: 'WorkflowEdgeModel' })
  .openapi('WorkflowEdgeModelInput')

