const WorkflowEdgeModelOutputSchema = z
  .object({
    source: z.string().openapi({ title: 'Source', description: 'ID of the source node.' }),
    target: z.string().openapi({ title: 'Target', description: 'ID of the target node.' }),
    forward_condition: z
      .union([
        z
          .xor([
            WorkflowUnconditionalModelOutputSchema.openapi({
              description: 'Condition that is always true.',
            }),
            WorkflowLLMConditionModelOutputSchema.openapi({
              description: 'Condition described using human language and evaluated by an LLM.',
            }),
            WorkflowResultConditionModelOutputSchema.openapi({
              description: 'Condition based on the result of the last executed tool dispatch node.',
            }),
            WorkflowExpressionConditionModelOutputSchema.openapi({
              description: 'Condition described using a deterministic expression.',
            }),
          ])
          .openapi({
            discriminator: {
              propertyName: 'type',
              mapping: {
                expression: '#/components/schemas/WorkflowExpressionConditionModel-Output',
                llm: '#/components/schemas/WorkflowLLMConditionModel-Output',
                result: '#/components/schemas/WorkflowResultConditionModel-Output',
                unconditional: '#/components/schemas/WorkflowUnconditionalModel-Output',
              },
            },
          }),
        z.null().nullable(),
      ])
      .openapi({
        title: 'Forward Condition',
        description:
          'Condition that must be met for the edge to be traversed in the forward direction (source to target).',
      }),
    backward_condition: z
      .union([
        z
          .xor([
            WorkflowUnconditionalModelOutputSchema.openapi({
              description: 'Condition that is always true.',
            }),
            WorkflowLLMConditionModelOutputSchema.openapi({
              description: 'Condition described using human language and evaluated by an LLM.',
            }),
            WorkflowResultConditionModelOutputSchema.openapi({
              description: 'Condition based on the result of the last executed tool dispatch node.',
            }),
            WorkflowExpressionConditionModelOutputSchema.openapi({
              description: 'Condition described using a deterministic expression.',
            }),
          ])
          .openapi({
            discriminator: {
              propertyName: 'type',
              mapping: {
                expression: '#/components/schemas/WorkflowExpressionConditionModel-Output',
                llm: '#/components/schemas/WorkflowLLMConditionModel-Output',
                result: '#/components/schemas/WorkflowResultConditionModel-Output',
                unconditional: '#/components/schemas/WorkflowUnconditionalModel-Output',
              },
            },
          }),
        z.null().nullable(),
      ])
      .openapi({
        title: 'Backward Condition',
        description:
          'Condition that must be met for the edge to be traversed in the backward direction (target to source).',
      }),
  })
  .openapi({
    required: ['source', 'target', 'forward_condition', 'backward_condition'],
    title: 'WorkflowEdgeModel',
  })
  .openapi('WorkflowEdgeModelOutput')

