const WorkflowPhoneNumberNodeModelOutputSchema = z
  .object({
    custom_sip_headers: z
      .array(
        z
          .xor([CustomSIPHeaderSchema, CustomSIPHeaderWithDynamicVariableSchema])
          .openapi({
            discriminator: {
              propertyName: 'type',
              mapping: {
                dynamic: '#/components/schemas/CustomSIPHeaderWithDynamicVariable',
                static: '#/components/schemas/CustomSIPHeader',
              },
            },
          }),
      )
      .max(20)
      .openapi({
        title: 'Custom Sip Headers',
        description:
          'Custom SIP headers to include when transferring the call. Each header can be either a static value or a dynamic variable reference.',
      }),
    transfer_destination: z
      .xor([
        PhoneNumberTransferDestinationSchema,
        SIPUriTransferDestinationSchema,
        PhoneNumberDynamicVariableTransferDestinationSchema,
        SIPUriDynamicVariableTransferDestinationSchema,
      ])
      .openapi({
        title: 'Transfer Destination',
        discriminator: {
          propertyName: 'type',
          mapping: {
            phone: '#/components/schemas/PhoneNumberTransferDestination',
            phone_dynamic_variable:
              '#/components/schemas/PhoneNumberDynamicVariableTransferDestination',
            sip_uri: '#/components/schemas/SIPUriTransferDestination',
            sip_uri_dynamic_variable:
              '#/components/schemas/SIPUriDynamicVariableTransferDestination',
          },
        },
      }),
    transfer_type: TransferTypeEnumSchema.default('conference'),
    sip_refer_play_dialtone: z
      .boolean()
      .default(true)
      .openapi({
        title: 'Sip Refer Play Dialtone',
        description:
          'When True, a ringing tone is played on the original call leg while a SIP REFER transfer completes. The tone is carried over RTP to the SIP peer executing the REFER, so disable this if the receiving system (e.g. an SBC or contact center) should not hear it. When disabled the caller hears silence until the transfer completes. SIP REFER transfers only.',
      }),
    uui: z
      .union([UUITransferConfigSchema, z.null().nullable()])
      .openapi({
        description:
          'User-to-User Information (RFC 7433) to attach to SIP REFER transfers. Carries call context such as CRM identifiers or escalation reason across the transfer boundary.',
      }),
    post_dial_digits: z
      .union([
        z
          .xor([PostDialDigitsStaticSchema, PostDialDigitsDynamicVariableSchema])
          .openapi({
            discriminator: {
              propertyName: 'type',
              mapping: {
                dynamic: '#/components/schemas/PostDialDigitsDynamicVariable',
                static: '#/components/schemas/PostDialDigitsStatic',
              },
            },
          }),
        z.null().nullable(),
      ])
      .openapi({
        title: 'Post Dial Digits',
        description:
          "DTMF digits to send after call connects (e.g., 'ww1234' for extension). Can be either a static value or a dynamic variable reference. Use 'w' for 0.5s pause. Only supported for Twilio transfers.",
      }),
    type: z.literal('phone_number').default('phone_number').openapi({ title: 'Type' }),
    position: PositionOutputSchema.openapi({
      description: 'Position of the node in the workflow.',
    }),
    edge_order: z
      .array(z.string())
      .openapi({
        title: 'Edge Order',
        description: 'The ids of outgoing edges in the order they should be evaluated.',
      }),
  })
  .openapi({
    required: [
      'custom_sip_headers',
      'transfer_destination',
      'transfer_type',
      'sip_refer_play_dialtone',
      'uui',
      'post_dial_digits',
      'type',
      'position',
      'edge_order',
    ],
    title: 'WorkflowPhoneNumberNodeModel',
  })
  .openapi('WorkflowPhoneNumberNodeModelOutput')

const EffectsSpecOutputSchema = z
  .object({
    filter_preset_id: z
      .union([z.string(), z.null().nullable()])
      .openapi({
        title: 'Filter Preset Id',
        description:
          'ID of a filter preset that colors the voice, such as `phone` or `old_radio`. List valid IDs with `GET /v1/audio-effects/catalog`.',
      }),
    distance: z
      .number()
      .min(0)
      .max(1)
      .default(0)
      .openapi({
        title: 'Distance',
        description:
          'How far the speaker sounds from the microphone, from 0 (close, unchanged) to 1 (far). Higher values roll off low and high frequencies and, when an environment is set, shift the balance from the dry voice toward the reverb.',
      }),
    environment_id: z
      .union([z.string(), z.null().nullable()])
      .openapi({
        title: 'Environment Id',
        description:
          'ID of a reverb environment that places the voice in a space, such as `small_room` or `hall`. List valid IDs with `GET /v1/audio-effects/catalog`. Reverb is rendered in stereo and adds a tail of up to several seconds after the speech ends.',
      }),
    background_noise_id: z
      .union([z.string(), z.null().nullable()])
      .openapi({
        title: 'Background Noise Id',
        description:
          'ID of a background noise bed looped under the voice, such as `cafe` or `keyboard`. List valid IDs with `GET /v1/audio-effects/catalog`.',
      }),
    send_level: z
      .number()
      .min(0)
      .max(1)
      .default(1)
      .openapi({
        title: 'Send Level',
        description:
          'How much of the voice feeds the reverb, from 0 (none) to 1 (full). Only applies when `environment_id` is set; 0 turns the reverb off.',
      }),
    pan: z
      .number()
      .min(-1)
      .max(1)
      .default(0)
      .openapi({
        title: 'Pan',
        description:
          'Stereo position of the voice, from -1 (hard left) through 0 (center) to 1 (hard right). Only the voice is panned; reverb and background noise stay centered.',
      }),
  })
  .openapi({
    required: [
      'filter_preset_id',
      'distance',
      'environment_id',
      'background_noise_id',
      'send_level',
      'pan',
    ],
    title: 'EffectsSpec',
    description:
      'Audio effects applied to generated speech: a filter preset, perceived distance, a reverb\nenvironment, a background noise bed, and stereo panning. Leave every field at its default\nto get unprocessed audio.',
  })
  .openapi('EffectsSpecOutput')

