const AgentWorkflowResponseModelSchema = z
  .object({
    edges: z.record(z.string(), WorkflowEdgeModelOutputSchema).openapi({ title: 'Edges' }),
    nodes: z
      .record(
        z.string(),
        z
          .xor([
            WorkflowStartNodeModelOutputSchema.openapi({
              description: 'Entry point of the workflow.',
            }),
            WorkflowEndNodeModelOutputSchema.openapi({
              description: 'Terminates the conversation upon reaching this node.',
            }),
            WorkflowPhoneNumberNodeModelOutputSchema.openapi({
              description: 'Transfers the conversation to a phone number.',
            }),
            WorkflowOverrideAgentNodeModelOutputSchema.openapi({
              description:
                'A subagent conducting the conversation until one of the exit conditions is met. Each subagent can override the base settings, changing the prompt, knowledge base, and more.',
            }),
            WorkflowStandaloneAgentNodeModelOutputSchema.openapi({
              description: 'Transfer the conversation to a standalone agent.',
            }),
            WorkflowToolNodeModelOutputSchema.openapi({
              description: 'Executes one or more tools in parallel.',
            }),
          ])
          .openapi({
            discriminator: {
              propertyName: 'type',
              mapping: {
                end: '#/components/schemas/WorkflowEndNodeModel-Output',
                override_agent: '#/components/schemas/WorkflowOverrideAgentNodeModel-Output',
                phone_number: '#/components/schemas/WorkflowPhoneNumberNodeModel-Output',
                standalone_agent: '#/components/schemas/WorkflowStandaloneAgentNodeModel-Output',
                start: '#/components/schemas/WorkflowStartNodeModel-Output',
                tool: '#/components/schemas/WorkflowToolNodeModel-Output',
              },
            },
          }),
      )
      .refine((val) => Object.keys(val).length >= 1)
      .openapi({ title: 'Nodes' }),
    prevent_subagent_loops: z
      .boolean()
      .default(false)
      .openapi({
        title: 'Prevent Subagent Loops',
        description: 'Whether to prevent loops in the workflow execution.',
      }),
  })
  .openapi({
    required: ['edges', 'nodes', 'prevent_subagent_loops'],
    title: 'AgentWorkflowResponseModel',
    example: {
      edges: {
        entry_to_tool_a: {
          forward_condition: { condition: 'Tool A condition', type: 'llm' },
          source: 'entry_node',
          target: 'tool_node_a',
        },
        start_to_entry: {
          forward_condition: { type: 'unconditional' },
          source: 'start_node',
          target: 'entry_node',
        },
        tool_a_to_failure: {
          forward_condition: { successful: false, type: 'result' },
          source: 'tool_node_a',
          target: 'failure_node',
        },
        tool_a_to_tool_b: {
          forward_condition: { successful: true, type: 'result' },
          source: 'tool_node_a',
          target: 'tool_node_b',
        },
        tool_b_to_agent_transfer: {
          forward_condition: { type: 'unconditional' },
          source: 'tool_node_b',
          target: 'success_transfer',
        },
        tool_b_to_conversation: {
          forward_condition: { condition: 'Conversation condition', type: 'llm' },
          source: 'tool_node_b',
          target: 'success_conversation',
        },
        tool_b_to_end: {
          forward_condition: { condition: 'End condition', type: 'llm' },
          source: 'tool_node_b',
          target: 'success_end',
        },
        tool_b_to_phone: {
          forward_condition: {
            expression: {
              children: [
                { name: 'force_phone_transfer', type: 'dynamic_variable' },
                {
                  prompt: 'Phone condition',
                  type: 'llm',
                  value_schema: { description: 'Phone condition', type: 'boolean' },
                },
                {
                  left: { name: 'mode', type: 'dynamic_variable' },
                  right: { type: 'string_literal', value: 'dev' },
                  type: 'eq_operator',
                },
              ],
              type: 'or_operator',
            },
            type: 'expression',
          },
          source: 'tool_node_b',
          target: 'success_phone',
        },
      },
      nodes: {
        entry_node: {
          additional_knowledge_base: [],
          additional_prompt: '',
          additional_tool_ids: [],
          conversation_config: {},
          edge_order: ['entry_to_tool_a'],
          entry_behavior: 'auto',
          label: 'Entry',
          position: { x: 0, y: 0 },
          type: 'override_agent',
        },
        failure_node: {
          additional_knowledge_base: [],
          additional_prompt: '',
          additional_tool_ids: [],
          conversation_config: {},
          edge_order: [],
          entry_behavior: 'auto',
          label: 'Failure',
          position: { x: 0, y: 0 },
          type: 'override_agent',
        },
        start_node: { edge_order: ['start_to_entry'], position: { x: 0, y: 0 }, type: 'start' },
        success_conversation: {
          additional_knowledge_base: [],
          additional_prompt: '',
          additional_tool_ids: [],
          conversation_config: {},
          edge_order: [],
          entry_behavior: 'auto',
          label: 'Success A',
          position: { x: 0, y: 0 },
          type: 'override_agent',
        },
        success_end: { edge_order: [], outcome: 'success', position: { x: 0, y: 0 }, type: 'end' },
        success_phone: {
          custom_sip_headers: [],
          edge_order: [],
          position: { x: 0, y: 0 },
          require_acceptance: false,
          sip_refer_play_dialtone: true,
          transfer_destination: { phone_number: '+1234567890', type: 'phone' },
          transfer_type: 'conference',
          type: 'phone_number',
        },
        success_transfer: {
          agent_id: 'success_transfer_agent',
          delay_ms: 0,
          drop_history: false,
          edge_order: [],
          enable_transferred_agent_first_message: false,
          isolate_history: false,
          position: { x: 0, y: 0 },
          preserve_client_tts_overrides: false,
          preserve_voice_settings: false,
          type: 'standalone_agent',
        },
        tool_node_a: {
          edge_order: ['tool_a_to_failure', 'tool_a_to_tool_b'],
          position: { x: 0, y: 0 },
          tools: [{ tool_id: 'tool_a' }, { tool_id: 'tool_b' }],
          type: 'tool',
        },
        tool_node_b: {
          edge_order: [
            'tool_b_to_conversation',
            'tool_b_to_end',
            'tool_b_to_phone',
            'tool_b_to_agent_transfer',
          ],
          position: { x: 0, y: 0 },
          tools: [{ tool_id: 'tool_a' }],
          type: 'tool',
        },
      },
      prevent_subagent_loops: false,
      subgraphs: {},
    },
  })
  .openapi('AgentWorkflowResponseModel')

