const PricingModeSchema = z
  .enum(['fixed', 'quote'])
  .default('fixed')
  .openapi({
    title: 'PricingMode',
    description:
      "Whether a catalog item's price and duration are known up front.\n\nOrthogonal to :class:`SMBServiceKind`, which describes the *resource*\nmodel (staff / asset / seats) rather than the price. A quotable service\ncan still be staff-delivered or asset-based, so this cannot be folded\ninto the kind discriminator.\n\n- ``FIXED``: catalog price and duration apply (the default, and every\n  pre-existing item).\n- ``QUOTE``: neither is knowable until the owner has seen the job. The\n  agent collects intake answers and files a quote request instead of\n  booking a slot or taking an order.",
  })
  .openapi('PricingMode')

const IntakeQuestionKindSchema = z
  .enum(['text', 'number', 'choice'])
  .default('text')
  .openapi({
    title: 'IntakeQuestionKind',
    description: 'Answer shape for a per-item intake question.',
  })
  .openapi('IntakeQuestionKind')

const SMBIntakeQuestionSchema = z
  .object({
    id: z
      .string()
      .exactOptional()
      .openapi({
        title: 'Id',
        description:
          'Stable identifier referenced by stored answers. Survives label edits so history stays attributable to the right question.',
      }),
    label: StrippedStrSchema.openapi({
      description:
        "The question as the agent should ask it, e.g. 'How many rooms?'. Phrased by the owner; the agent may rephrase for conversational flow but must not change what is being asked.",
    }),
    kind: IntakeQuestionKindSchema.default('text').exactOptional(),
    options: z
      .array(StrippedStrSchema)
      .max(20)
      .exactOptional()
      .openapi({
        title: 'Options',
        description: "Allowed answers for ``kind='choice'``. Must be empty for the other kinds.",
      }),
    required: z
      .boolean()
      .default(false)
      .exactOptional()
      .openapi({
        title: 'Required',
        description:
          "On the public booking page this is enforced as a form constraint. On a voice call it is only an instruction to the agent: hard-rejecting a booking mid-conversation because the caller dodged a question is worse for the caller than a booking with a gap the owner can chase. Do not 'fix' this into a server-side constraint for the voice path.",
      }),
    is_active: z
      .boolean()
      .default(true)
      .exactOptional()
      .openapi({
        title: 'Is Active',
        description:
          'Retired questions are deactivated rather than deleted, so answers already stored against them keep resolving.',
      }),
  })
  .openapi({
    required: ['label'],
    title: 'SMBIntakeQuestion',
    description:
      'One owner-authored question the agent asks before booking/ordering this item.\n\nThis is the structured counterpart to the agent-wide\n``CustomerFacingConfig.details_to_collect``: scoped to a single catalog\nitem, and typed so the answer is usable afterwards (rendered in the inbox,\nfilterable, and eventually an input to pricing) rather than just readable.',
  })
  .openapi('SMBIntakeQuestion')

