const EnvironmentVariableResponseSchema = z
  .object({
    label: z.string().openapi({ title: 'Label' }),
    created_at_unix_secs: z.int().openapi({ title: 'Created At Unix Secs' }),
    updated_at_unix_secs: z.int().openapi({ title: 'Updated At Unix Secs' }),
    created_by_user_id: z
      .union([z.string(), z.null().nullable()])
      .exactOptional()
      .openapi({ title: 'Created By User Id' }),
    type: z.enum(['string', 'secret', 'auth_connection']).openapi({ title: 'Type' }),
    id: z.string().openapi({ title: 'Id' }),
    workspace_id: z.string().openapi({ title: 'Workspace Id' }),
    values: z
      .union([
        z.record(z.string(), z.string()),
        z.record(z.string(), EnvironmentVariableSecretValueSchema),
        z.record(z.string(), EnvironmentVariableAuthConnectionValueSchema),
      ])
      .openapi({ title: 'Values' }),
  })
  .openapi({
    required: [
      'label',
      'created_at_unix_secs',
      'updated_at_unix_secs',
      'type',
      'id',
      'workspace_id',
      'values',
    ],
    title: 'EnvironmentVariableResponse',
  })
  .openapi('EnvironmentVariableResponse')

