const InvoiceResponseModelSchema = z
  .object({
    amount_due_cents: z
      .int()
      .openapi({ title: 'Amount Due Cents', description: 'The amount due in cents.' }),
    subtotal_cents: z
      .union([z.int(), z.null().nullable()])
      .exactOptional()
      .openapi({
        title: 'Subtotal Cents',
        description: 'The subtotal amount in cents before tax (exclusive of tax and discounts).',
      }),
    tax_cents: z
      .union([z.int(), z.null().nullable()])
      .exactOptional()
      .openapi({ title: 'Tax Cents', description: 'The tax amount in cents.' }),
    discount_percent_off: z
      .union([z.number(), z.null().nullable()])
      .exactOptional()
      .openapi({
        title: 'Discount Percent Off',
        description:
          'Deprecated. Use [discounts] instead. The discount applied to the invoice. E.g. [20.0f] for 20% off.',
      }),
    discount_amount_off: z
      .union([z.number(), z.null().nullable()])
      .exactOptional()
      .openapi({
        title: 'Discount Amount Off',
        description:
          'Deprecated. Use [discounts] instead. The discount applied to the invoice. E.g. [20.0f] for 20 cents off.',
      }),
    discounts: z
      .array(DiscountResponseModelSchema)
      .openapi({ title: 'Discounts', description: 'The discounts applied to the invoice.' }),
    next_payment_attempt_unix: z
      .int()
      .openapi({
        title: 'Next Payment Attempt Unix',
        description:
          'The Unix timestamp of the next payment attempt. -1 when there is no next payment attempt.',
      }),
    payment_intent_status: z
      .union([
        z.enum([
          'canceled',
          'processing',
          'requires_action',
          'requires_capture',
          'requires_confirmation',
          'requires_payment_method',
          'succeeded',
        ]),
        z.null().nullable(),
      ])
      .openapi({
        title: 'Payment Intent Status',
        description:
          "Deprecated. Use [payment_intent_statusses] instead. The status of this invoice's first payment intent. None when there is no payment intent.",
      }),
    payment_intent_statusses: z
      .array(
        z.enum([
          'canceled',
          'processing',
          'requires_action',
          'requires_capture',
          'requires_confirmation',
          'requires_payment_method',
          'succeeded',
        ]),
      )
      .openapi({
        title: 'Payment Intent Statusses',
        description:
          "The statuses of this invoice's payment intents. Empty list when there are no payment intents.",
      }),
  })
  .openapi({
    required: [
      'amount_due_cents',
      'discounts',
      'next_payment_attempt_unix',
      'payment_intent_status',
      'payment_intent_statusses',
    ],
    title: 'InvoiceResponseModel',
    example: {
      amount_due_cents: 1000,
      discounts: [{ discount_percent_off: 20 }],
      next_payment_attempt_unix: 1738356858,
      payment_intent_status: 'processing',
      payment_intent_statusses: ['processing', 'succeeded'],
      subtotal_cents: 900,
      tax_cents: 100,
    },
  })
  .openapi('InvoiceResponseModel')

