const MCPServerConfigInputSchema = z
  .object({
    approval_policy: MCPApprovalPolicySchema.default('require_approval_all').exactOptional(),
    tool_approval_hashes: z
      .array(MCPToolApprovalHashSchema)
      .exactOptional()
      .openapi({
        title: 'Tool Approval Hashes',
        description:
          'List of tool approval hashes for per-tool approval when approval_policy is REQUIRE_APPROVAL_PER_TOOL',
      }),
    transport: MCPServerTransportSchema.default('SSE')
      .exactOptional()
      .openapi({ description: 'The transport type used to connect to the MCP server' }),
    url: z
      .union([z.string(), ConvAISecretLocatorSchema])
      .openapi({
        title: 'Url',
        description:
          'The URL of the MCP server, if this contains a secret please store as a workspace secret, otherwise store as a plain string. Must use https',
      }),
    secret_token: z
      .union([ConvAISecretLocatorSchema, ConvAIUserSecretDBModelSchema, z.null().nullable()])
      .exactOptional()
      .openapi({
        title: 'Secret Token',
        description:
          'The secret token (Authorization header) stored as a workspace secret or in-place secret',
      }),
    request_headers: z
      .record(
        z.string(),
        z.union([
          z.string(),
          ConvAISecretLocatorSchema,
          ConvAIDynamicVariableSchema,
          ConvAIEnvVarLocatorSchema,
        ]),
      )
      .exactOptional()
      .openapi({ title: 'Request Headers', description: 'The headers included in the request' }),
    request_meta: z
      .record(
        z.string(),
        z.union([
          z.string(),
          z.int(),
          z.number(),
          z.boolean(),
          ConvAISecretLocatorSchema,
          ConvAIDynamicVariableSchema,
          ConvAIEnvVarLocatorSchema,
        ]),
      )
      .exactOptional()
      .openapi({
        title: 'Request Meta',
        description:
          'Entries sent in the MCP `_meta` field of tools/call requests. Values may be JSON scalars, or references to a workspace secret, dynamic variable, or environment variable resolved per call.',
      }),
    auth_connection: z
      .union([
        AuthConnectionLocatorSchema,
        EnvironmentAuthConnectionLocatorSchema,
        z.null().nullable(),
      ])
      .exactOptional()
      .openapi({
        title: 'Auth Connection',
        description: 'Optional auth connection to use for authentication with this MCP server',
      }),
    name: z.string().openapi({ title: 'Name' }),
    description: z.string().default('').exactOptional().openapi({ title: 'Description' }),
    force_pre_tool_speech: z
      .boolean()
      .default(false)
      .exactOptional()
      .openapi({
        title: 'Force Pre Tool Speech',
        description:
          'DEPRECATED: use `pre_tool_speech` instead. If true, all tools from this MCP server will require pre-tool execution speech.',
        deprecated: true,
      }),
    pre_tool_speech: PreToolSpeechModeSchema.default('auto')
      .exactOptional()
      .openapi({
        description:
          "Controls whether the agent speaks before this tool is called. 'auto' (default) decides based on recent tool latency, 'force' always asks the agent to speak, 'off' fully opts out regardless of latency. Applies to every tool from this MCP server unless overridden per tool.",
      }),
    disable_interruptions: z
      .boolean()
      .default(false)
      .exactOptional()
      .openapi({
        title: 'Disable Interruptions',
        description:
          'DEPRECATED: use `interruption_mode` instead. If true, the user will not be able to interrupt the agent while any tool from this MCP server is running.',
        deprecated: true,
      }),
    interruption_mode: ToolInterruptionModeSchema.default('allow')
      .exactOptional()
      .openapi({
        description:
          "Controls whether the user can interrupt the agent around this tool call. 'allow' (default) lets the user interrupt at any time, 'disable_during_tool' suppresses interruptions only while the tool is running, 'disable_during_tool_and_turn' suppresses interruptions while the tool runs and for the agent response that follows it. Applies to every tool from this MCP server unless overridden per tool.",
      }),
    tool_call_sound: z
      .union([ToolCallSoundTypeSchema, z.null().nullable()])
      .exactOptional()
      .openapi({
        description:
          'Predefined tool call sound type to play during tool execution for all tools from this MCP server',
      }),
    tool_call_sound_behavior: ToolCallSoundBehaviorSchema.default('auto')
      .exactOptional()
      .openapi({
        description:
          'Determines when the tool call sound should play for all tools from this MCP server',
      }),
    execution_mode: ToolExecutionModeSchema.default('immediate')
      .exactOptional()
      .openapi({
        description:
          "Determines when and how all tools from this MCP server execute: 'immediate' executes the tool right away when requested by the LLM, 'post_tool_speech' waits for the agent to finish speaking before executing, 'async' runs the tool in the background without blocking - best for long-running operations.",
      }),
    response_timeout_secs: z
      .int()
      .min(5)
      .max(300)
      .default(30)
      .exactOptional()
      .openapi({
        title: 'Response Timeout Secs',
        description:
          'The maximum time in seconds to wait for each MCP tool call to complete. Must be between 5 and 300 seconds (inclusive).',
      }),
    tool_config_overrides: z
      .array(MCPToolConfigOverrideInputSchema)
      .exactOptional()
      .openapi({
        title: 'Tool Config Overrides',
        description:
          'List of per-tool configuration overrides that override the server-level defaults for specific tools',
      }),
    disable_compression: z
      .boolean()
      .default(false)
      .exactOptional()
      .openapi({
        title: 'Disable Compression',
        description:
          'Whether to disable HTTP compression for this MCP server. Enable this if the server does not support compressed responses.',
      }),
  })
  .openapi({ required: ['url', 'name'], title: 'MCPServerConfig' })
  .openapi('MCPServerConfigInput')

