const OrderResponseSchema = z
  .object({
    order_id: OrderIdSchema.openapi({ description: 'The ID of the order.' }),
    name: z.string().openapi({ title: 'Name', description: 'The display name of the order.' }),
    state: OrderStateSchema.openapi({ description: 'The current state of the order.' }),
    items: z
      .array(OrderItemInfoSchema)
      .openapi({
        title: 'Items',
        description: 'The list of items in this order with their quotes.',
      }),
    total_amount_usd: z
      .union([z.number(), z.null().nullable()])
      .exactOptional()
      .openapi({
        title: 'Total Amount Usd',
        description:
          'The total price for all items in USD. Excluded from response until quotes are available.',
      }),
    sandbox: z
      .boolean()
      .default(false)
      .exactOptional()
      .openapi({
        title: 'Sandbox',
        description:
          'Whether this is a sandbox order that auto-progresses without producer intervention.',
      }),
    created_at: z.iso
      .datetime({ offset: true })
      .openapi({ title: 'Created At', description: 'The timestamp when the order was created.' }),
    submitted_at: z
      .union([z.iso.datetime({ offset: true }), z.null().nullable()])
      .exactOptional()
      .openapi({
        title: 'Submitted At',
        description: 'The timestamp when the order was submitted, if applicable.',
      }),
    paid_at: z
      .union([z.iso.datetime({ offset: true }), z.null().nullable()])
      .exactOptional()
      .openapi({
        title: 'Paid At',
        description: 'The timestamp when payment was received, if applicable.',
      }),
    accepted_at: z
      .union([z.iso.datetime({ offset: true }), z.null().nullable()])
      .exactOptional()
      .openapi({
        title: 'Accepted At',
        description: 'The timestamp when the order was accepted for production, if applicable.',
      }),
    completed_at: z
      .union([z.iso.datetime({ offset: true }), z.null().nullable()])
      .exactOptional()
      .openapi({
        title: 'Completed At',
        description: 'The timestamp when the order was completed, if applicable.',
      }),
    cancel_reason: z
      .union([z.string(), z.null().nullable()])
      .exactOptional()
      .openapi({
        title: 'Cancel Reason',
        description: 'The reason the order was cancelled, if applicable.',
      }),
  })
  .openapi({
    required: ['order_id', 'name', 'state', 'items', 'created_at'],
    title: 'OrderResponse',
    example: {
      created_at: '2025-03-15T10:00:00Z',
      name: 'Spanish Dubs',
      order_id: 'prodorder_01jgatk6h0fwxrtbjade61yqhx',
      sandbox: false,
      state: 'open',
      total_amount_usd: 11,
    },
  })
  .openapi('OrderResponse')

